def rank(rows):
    piv = {}
    for v in rows:
        while v:
            k = v.bit_length() - 1
            if k not in piv:
                piv[k] = v
                break
            v ^= piv[k]
    return len(piv)

def main():
    env = {**os.environ, 'OPENBLAS_NUM_THREADS': '1', 'VECLIB_MAXIMUM_THREADS': '1', 'NUMBA_NUM_THREADS': '4', 'PYTHONDONTWRITEBYTECODE': '1'}
    for n in ['neutral_column_plaquette', 'neutral_column_parity_native']:
        run_probe([sys.executable, str(PACK / (n + '.py'))], env, 250)
    exact = json.loads((PACK / 'neutral_column_plaquette.json').read_text())
    native = json.loads((PACK / 'neutral_column_parity_native.json').read_text())
    checks = []
    for L in [5, 6]:
        for lam in [0.1, 0.2]:
            plus = next((r for r in native if r['L'] == L and r['lambda_perp'] == lam and (r['parity'] == 0)))
            minus = next((r for r in native if r['L'] == L and r['lambda_perp'] == lam and (r['parity'] == 1)))
            ratio = (minus['band_mean'] - plus['band_mean']) / lam ** 4
            pred = (L + 14) / 64
            assert max(plus['residuals'] + minus['residuals']) < 1e-10
            assert minus['ground'] > plus['ground'] and abs(ratio - pred) < 0.04 * lam ** 2
            c_ratio = (plus['readout_band_mean'] - minus['readout_band_mean']) / lam ** 4
            c_pred = -3 * (L + 13) / 64
            assert abs(c_ratio - c_pred) < 0.3 * lam ** 2
            checks.append(dict(L=L, lam=lam, splitting_over_lambda4=ratio, prediction=pred, readout_difference_over_lambda4=c_ratio, readout_prediction=c_pred))
    counts = []
    for nx in range(3, 8):
        for ny in range(3, 8):
            for periodic in [False, True]:
                rows = []
                for x in range(nx if periodic else nx - 1):
                    for y in range(ny if periodic else ny - 1):
                        rows.append(sum((1 << (x + a) % nx * ny + (y + b) % ny for a, b in [(0, 0), (1, 0), (0, 1), (1, 1)])))
                r = rank(rows)
                assert nx * ny - r == nx + ny - 1
                counts.append(dict(nx=nx, ny=ny, periodic=periodic, rank=r))
    print('RESULT_JSON', json.dumps(dict(inputs={f: hashlib.sha256((ROOT / f).read_bytes()).hexdigest() for f in AUDIT_INPUT_PATHS}, exact=exact, native=native, comparisons=checks, constraint_counts=counts, scope='Fixed-order native interaction and finite-size small-anisotropy parity preference; no uniform 3D phase or empirical claim'), indent=2) + '\n')

import tempfile, shutil
STAGING_PATHS = [('outputs/neutral_composite_continuation_review_2026_10_18/helpers/pr9730/neutral_column_parity_native.py', 'neutral_column_parity_native.py'), ('outputs/neutral_composite_continuation_review_2026_10_18/helpers/pr9730/neutral_column_plaquette.py', 'neutral_column_plaquette.py')]
PROBE_GROUPS = 0

def run_probe(command, env, timeout):
 global PROBE_GROUPS
 print("BEGIN_PROBE", Path(command[1]).stem, flush=True)
 subprocess.run(command, env=env, cwd=PACK, timeout=timeout, check=True)
 PROBE_GROUPS += 1
 print("END_PROBE", Path(command[1]).stem, "completed", flush=True)

def execute():
 global PACK
 if sys.flags.optimize:
  raise RuntimeError("Scientific predicates require Python assertions enabled")
 with tempfile.TemporaryDirectory(prefix="neutral-pr9730-") as scratch:
  PACK = Path(scratch)
  for source, relative in STAGING_PATHS:
   target = PACK / relative
   target.parent.mkdir(parents=True, exist_ok=True)
   shutil.copyfile(ROOT / source, target)
  main()
  print('per_element: All signed square paths and canonical fourth-order parity coefficients are reconstructed.')
  print('per_site: Existing physical spins supply aligned column coordinates at the stated finite lengths.')
  print('per_mode: Native finite parity spectra and original-source derivatives are compared with fixed coefficients.')
  print('per_block: Finite rectangular constraint ranks are checked; no uniform three-dimensional phase is inferred.')
  print("lattice_wide: Infinite native spectra, physical state/readout supply and observational identification remain outside these finite controls.")
  print("Count unit: completed finite probe groups; aggregate predicates and child assertions must all succeed.")
  print(f"TOTAL: PASS={PROBE_GROUPS} FAIL=0")

if __name__ == "__main__":
 execute()
